export class PipeCollector {
  collect(stream: LineStream): string {
    const chunks: string[] = []
    let current = stream.readLine()
    while (current !== null) {
      chunks.push(current)
      current = stream.readLine()
    }
    return chunks.join(' ')
  }
  label(): string {
    return 'process output line reader accumulation'
  }
}

